import Foundation\n\n// MARK: - Notification Names\nextension NSNotification.Name {\n    static let didLogin = NSNotification.Name(\"didLogin\")\n    static let didLogout = NSNotification.Name(\"didLogout\")\n    static let didWinGame = NSNotification.Name(\"didWinGame\")\n    static let didLoseGame = NSNotification.Name(\"didLoseGame\")\n    static let balanceUpdated = NSNotification.Name(\"balanceUpdated\")\n    static let levelUpNotification = NSNotification.Name(\"levelUp\")\n    static let paymentProcessed = NSNotification.Name(\"paymentProcessed\")\n    static let withdrawalRequested = NSNotification.Name(\"withdrawalRequested\")\n}\n\n// MARK: - User Defaults Keys\nstruct UserDefaultsKeys {\n    static let userId = \"userId\"\n    static let username = \"username\"\n    static let balance = \"balance\"\n    static let lastLoginDate = \"lastLoginDate\"\n    static let gamesPlayed = \"gamesPlayed\"\n    static let totalWinnings = \"totalWinnings\"\n    static let totalLosses = \"totalLosses\"\n    static let level = \"level\"\n    static let soundEnabled = \"soundEnabled\"\n    static let hapticsEnabled = \"hapticsEnabled\"\n    static let authToken = \"authToken\"\n    static let userEmail = \"userEmail\"\n}\n\n// MARK: - Analytics Events\nclass AnalyticsEvent {\n    static let appLaunched = \"app_launched\"\n    static let gameStarted = \"game_started\"\n    static let gameCompleted = \"game_completed\"\n    static let gameLost = \"game_lost\"\n    static let gameWon = \"game_won\"\n    static let depositMade = \"deposit_made\"\n    static let withdrawalMade = \"withdrawal_made\"\n    static let leveledUp = \"leveled_up\"\n    static let achievementUnlocked = \"achievement_unlocked\"\n    static let screenViewed = \"screen_viewed\"\n    static let paymentInitiated = \"payment_initiated\"\n    static let paymentFailed = \"payment_failed\"\n    static let paymentSucceeded = \"payment_succeeded\"\n}\n\n// MARK: - Payment Provider Keys\nclass PaymentProviderKeys {\n    // Stripe\n    static let stripePublishableKey = \"pk_live_your_publishable_key\"\n    static let stripeSecretKey = \"sk_live_your_secret_key\" // Never expose in app\n    \n    // PayPal\n    static let paypalClientId = \"your_paypal_client_id\"\n    static let paypalMode = \"live\" // \"sandbox\" for testing\n    \n    // Apple Pay\n    static let appleMerchantId = \"merchant.your.company\"\n    \n    // Skrill\n    static let skrillAccountEmail = \"your_skrill_email@example.com\"\n    static let skrillApiKey = \"your_skrill_api_key\"\n    \n    // Neteller\n    static let netellerAccountEmail = \"your_neteller_email@example.com\"\n    static let netellerApiKey = \"your_neteller_api_key\"\n}\n\n// MARK: - Game Provider Keys\nclass GameProviderKeys {\n    // Microgaming\n    static let microgamingApiKey = \"your_microgaming_api_key\"\n    static let microgamingVendorId = \"your_vendor_id\"\n    \n    // Playtech\n    static let playtechApiKey = \"your_playtech_api_key\"\n    static let playtechBrandId = \"your_brand_id\"\n    \n    // Pragmatic Play\n    static let pragmaticPlayApiKey = \"your_pragmatic_play_api_key\"\n    static let pragmaticPlayOperatorId = \"your_operator_id\"\n    \n    // NetEnt\n    static let netentApiKey = \"your_netent_api_key\"\n    static let netentOperatorId = \"your_operator_id\"\n}\n\n// MARK: - API Endpoints\nclass APIEndpoints {\n    static let baseURL = \"https://api.youronlinecasino.com\"\n    static let authURL = \"\(baseURL)/auth\"\n    static let gamesURL = \"\(baseURL)/games\"\n    static let paymentsURL = \"\(baseURL)/payments\"\n    static let usersURL = \"\(baseURL)/users\"\n    static let transactionsURL = \"\(baseURL)/transactions\"\n}\n